// Citations in several styles — window.Cite.
//
// Requirement (2026-10-29): show how a paper is cited, in the text and in
// a reference list, in several styles, on its info page; export the
// references of every paper in a project. Generated by script, and the
// formatting must be right — so the rules are not written here. They come
// from the official CSL style files (src/vendor/citeproc/styles/, the
// files Zotero and Mendeley use), run by citeproc-js, the reference CSL
// engine (src/vendor/citeproc/citeproc.js). citeproc-py was tried first
// and rejected: it printed initials where MLA and Chicago print full
// names and left punctuation outside closing quotes.
//
// The items come from the server (python/cite_api.py): one CSL-JSON
// mapping of a paper's summary, with `title-sentence` for the styles that
// want sentence case.
//
// Relies at call time on: window.CSL (citeproc.js), fetch.

window.Cite = (function () {
  "use strict";

  // The styles offered, in menu order. `locale`: the style's language
  // (none of the files declares one; Cite Them Right is British —
  // single quotes, punctuation outside). `sentenceCase`: the style wants
  // article and book titles in sentence case (APA 7 §6.17, NLM/Vancouver,
  // IEEE); the others print titles in title case themselves.
  const STYLES = [
    { id: "apa", label: "APA 7th", file: "apa.csl", locale: "en-US", sentenceCase: true },
    { id: "mla", label: "MLA 9th", file: "modern-language-association.csl", locale: "en-US", sentenceCase: false, numberAsPage: true },
    { id: "chicago", label: "Chicago (author-date)", file: "chicago-author-date.csl", locale: "en-US", sentenceCase: false },
    { id: "harvard", label: "Harvard (Cite Them Right)", file: "harvard-cite-them-right.csl", locale: "en-GB", sentenceCase: false },
    { id: "vancouver", label: "Vancouver", file: "vancouver.csl", locale: "en-US", sentenceCase: true },
    { id: "ieee", label: "IEEE", file: "ieee.csl", locale: "en-US", sentenceCase: true },
  ];
  const BASE = "/vendor/citeproc/";

  const _files = {};
  async function _text(path) {
    if (!(path in _files)) {
      const r = await fetch(BASE + path);
      if (!r.ok) throw new Error(`${path}: HTTP ${r.status}`);
      _files[path] = await r.text();
    }
    return _files[path];
  }

  function styleById(id) { return STYLES.find(s => s.id === id) || STYLES[0]; }

  /** The item as this style should see it: sentence-case title where the
   *  style wants one. `title-sentence` is Corpus's own field; CSL ignores
   *  unknown fields, but it is removed so nothing depends on that. */
  function itemFor(style, item) {
    const out = { ...item };
    if (style.sentenceCase && item["title-sentence"]) out.title = item["title-sentence"];
    if (style.sentenceCase && item["container-title-sentence"]) out["container-title"] = item["container-title-sentence"];
    delete out["title-sentence"];
    delete out["container-title-sentence"];
    // MLA's style file reads `number` as an issue number, so an article
    // number printed as a second "no." beside the real issue. It is the
    // article's location, so MLA gets it as the page. (APA and Chicago
    // read `number` correctly: "Article e123", "123 (17): e123".)
    if (style.numberAsPage && out.number && !out.page) { out.page = out.number; delete out.number; }
    return out;
  }

  /** Format `items` in `styleId`. Returns, per item in input order,
   *  {id, intext, reference} in `format` ("html" or "text"), plus the
   *  whole `bibliography` in the style's own order. Async only because
   *  the style and locale files are fetched once. `files` lets tests
   *  supply them directly. */
  async function format(items, styleId, fmt = "html", files = null) {
    const style = styleById(styleId);
    const get = files ? (p => files[p]) : _text;
    const xml = await get("styles/" + style.file);
    const locale = await get(`locales/locales-${style.locale}.xml`);
    const byId = Object.fromEntries(items.map(it => [it.id, itemFor(style, it)]));
    const engine = new CSL.Engine({ retrieveLocale: () => locale, retrieveItem: id => byId[id] },
                                  xml, style.locale, true);
    engine.setOutputFormat(fmt);
    const ids = items.map(it => it.id);
    engine.updateItems(ids);
    const [meta, entries] = engine.makeBibliography();
    const bibliography = entries.map(e => e.trim());
    const refById = Object.fromEntries(meta.entry_ids.map((idList, i) => [idList[0], bibliography[i]]));
    const cite = (ci) => engine.previewCitationCluster(
      { citationItems: [ci], properties: { noteIndex: 0 } }, [], [], fmt);
    const rows = ids.map(id => {
      // Narrative form ("Grady et al. (2019)") is the style's own author-
      // only cite followed by its author-suppressed cite; a style with no
      // year in its cites (MLA) gives just the authors.
      const who = cite({ id, "author-only": true });
      const rest = cite({ id, "suppress-author": true });
      // citeproc-js prints "[NO_PRINTED_FORM]" when nothing is left.
      const bare = toPlain(rest).replace("[NO_PRINTED_FORM]", "").replace(/[()\[\]\s]/g, "");
      return { id, intext: cite({ id }), reference: refById[id] || "",
               narrative: bare ? `${who} ${rest}` : who };
    });
    return { style: style.id, rows, bibliography };
  }

  /** HTML (italics) → plain text with no markup, for "Copy as text". */
  function toPlain(html) {
    return String(html).replace(/<[^>]+>/g, "")
      .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
      .replace(/&#38;/g, "&").replace(/&quot;/g, '"').replace(/&#39;/g, "'").trim();
  }

  return { STYLES, format, toPlain, styleById, itemFor };
})();
